16		<title>Welcome - Accessible HTML5 Guide</title>
17		<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E👋%3C/text%3E%3C/svg%3E">
18		<style>
19			:root {
20				color-scheme: light dark;
21				--text: #1a1a1a;
22				--text-secondary: #555;
23				--background: #fff;
24				--surface: #fff;
25				--accent: #0052a3;
26				--border: #e0e0e0;
27				--border-control: #767676;
28				--error: #c62828;
29			}
30			@media (prefers-color-scheme: dark) {
31				:root {
32					--text: #e0e0e0;
33					--text-secondary: #a0a0a0;
34					--background: #121212;
35					--surface: #1e1e1e;
36					--accent: #5fa3ff;
37					--border: #333;
38					--border-control: #8c8c8c;
39					--error: #ff8a80;
40				}
41			}
42			*,
43			*::before,
44			*::after {
45				box-sizing: border-box;
46			}
47			html {
48				-webkit-text-size-adjust: 100%;
49				text-size-adjust: 100%;
50			}
51			@media (prefers-reduced-motion: no-preference) {
52				html {
53					scroll-behavior: smooth;
54				}
55				a {
56					transition: text-decoration-thickness 0.15s ease;
57				}
58				.skip-link {
59					transition: transform 0.15s ease;
60				}
61				button,
62				.button {
63					transition: filter 0.15s ease, transform 0.15s ease;
64				}
65			}
66			body {
67				display: grid;
68				grid-template-columns: minmax(0, 1fr);
69				grid-template-rows: auto 1fr auto;
70				min-height: 100vh;
71				min-height: 100dvh;
72				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
73				font-size: 1rem;
74				line-height: 1.6;
75				overflow-wrap: break-word;
76				max-width: 70ch;
77				margin: 0 auto;
78				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
79				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
80				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
81				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
82				color: var(--text);
83				background: var(--background);
84			}
85			h1 {
86				color: var(--accent);
87				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
88				font-weight: 700;
89				line-height: 1.1;
90				text-wrap: balance;
91				margin: 0 0 1.5rem 0;
92				letter-spacing: -0.02em;
93			}
94			h2 {
95				color: var(--accent);
96				font-size: clamp(1.25rem, 1rem + 1.5vw, 1.75rem);
97				font-weight: 600;
98				line-height: 1.2;
99				text-wrap: balance;
100				margin: 2rem 0 1rem 0;
101				letter-spacing: -0.01em;
102			}
103			h2:first-child {
104				margin-top: 0;
105			}
106			p {
107				text-wrap: pretty;
108				margin: 1rem 0;
109				line-height: 1.65;
110			}
111			a {
112				color: var(--accent);
113				text-underline-offset: 0.2em;
114				text-decoration-thickness: 2px;
115				text-decoration-skip-ink: auto;
116				font-weight: 500;
117			}
118			a:active {
119				text-decoration-thickness: 3px;
120			}
121			@media (hover: hover) {
122				a:hover {
123					text-decoration-thickness: 3px;
124				}
125			}
126			a[target="_blank"]::after {
127				content: "\2197" / "";
128				display: inline-block;
129				margin-inline-start: 0.2em;
130				font-size: 0.8em;
131				text-decoration: none;
132			}
133			button,
134			.button {
135				display: inline-block;
136				text-decoration: none;
137				padding: 0.75rem 1.5rem;
138				font-size: 1rem;
139				font-weight: 500;
140				font-family: inherit;
141				color: var(--background);
142				background: var(--accent);
143				border: 2px solid var(--accent);
144				border-radius: 0.25rem;
145				cursor: pointer;
146				white-space: nowrap;
147			}
148			@media (hover: hover) {
149				button:hover,
150				.button:hover {
151					filter: brightness(1.15);
152				}
153			}
154			button:active,
155			.button:active {
156				transform: scale(0.97);
157			}
158			ul, ol {
159				margin: 1rem 0;
160				padding-left: 2rem;
161			}
162			li {
163				margin: 0.5rem 0;
164			}
165			:focus-visible {
166				outline: 2px solid var(--accent);
167				outline-offset: 2px;
168			}
169			a:not(.button):focus-visible {
170				border-radius: 2px;
171			}
172			.skip-link {
173				position: absolute;
174				left: 0;
175				top: 0;
176				transform: translateY(-100%);
177				background: var(--accent);
178				color: var(--background);
179				padding: 0.75rem 1.5rem;
180				z-index: 1000;
181				border-radius: 0 0 0.25rem 0;
182				font-weight: 600;
183				text-decoration: none;
184				display: inline-block;
185			}
186			.skip-link:focus {
187				transform: translateY(0);
188				outline: 3px solid var(--text);
189				outline-offset: -3px;
190			}
191			header {
192				padding-block: 1.5rem 0;
193			}
194			nav ul {
195				display: flex;
196				flex-wrap: wrap;
197				gap: 0.5rem 1.5rem;
198				margin: 1rem 0 0 0;
199				padding: 0;
200				list-style: none;
201			}
202			nav li {
203				margin: 0;
204			}
205			footer nav ul {
206				justify-content: center;
207				margin: 0 0 1rem 0;
208			}
209			main {
210				padding: 1rem 0;
211			}
212			main:focus {
213				outline: none;
214			}
215			section {
216				margin: 2rem 0;
217			}
218			[id] {
219				scroll-margin-top: 1.5rem;
220			}
221			@media (forced-colors: active) {
222				.skip-link,
223				button,
224				.button {
225					border: 2px solid ButtonText;
226				}
227			}
228			.card {
229				border: 1px solid var(--border);
230				border-radius: 0.5rem;
231				padding: 1.5rem;
232				background: var(--surface);
233				margin: 1.5rem 0;
234			}
235			.card h3 {
236				font-size: 1.25rem;
237				line-height: 1.3;
238				text-wrap: balance;
239				margin-top: 0;
240				margin-bottom: 0.5rem;
241				color: var(--accent);
242			}
243			.visually-hidden {
244				position: absolute;
245				width: 1px;
246				height: 1px;
247				margin: -1px;
248				padding: 0;
249				overflow: hidden;
250				clip: rect(0, 0, 0, 0);
251				white-space: nowrap;
252				border: 0;
253			}
254			@media (prefers-contrast: more) {
255				:root {
256					--border: currentColor;
257					--border-control: currentColor;
258				}
259				button,
260				.button {
261					border-width: 3px;
262				}
263				.card {
264					border-width: 2px;
265				}
266			}
267			footer {
268				padding-block: 1.5rem;
269				border-top: 1px solid var(--border);
270				font-size: 0.875rem;
271				color: var(--text-secondary);
272				text-align: center;
273			}
274			footer p {
275				margin: 0.5rem 0;
276			}
277			small {
278				display: block;
279			}
280			kbd {
281				background: var(--surface);
282				border: 1px solid var(--border);
283				border-radius: 0.25rem;
284				padding: 0.125rem 0.375rem;
285				font-family: monospace;
286				font-size: 0.875em;
287			}
288			kbd kbd {
289				border: 0;
290				padding: 0;
291				background: none;
292				font-size: 1em;
293			}
294			.field {
295				margin-bottom: 1rem;
296			}
297			label {
298				display: block;
299				margin-bottom: 0.5rem;
300				font-weight: 500;
301			}
302			input,
303			textarea {
304				width: 100%;
305				padding: 0.5rem;
306				font: inherit;
307				color: var(--text);
308				background: var(--surface);
309				border: 1px solid var(--border-control);
310				border-radius: 0.25rem;
311			}
312			textarea {
313				resize: vertical;
314			}
315			#form-status:empty {
316				margin: 0;
317			}
318			.form-hint {
319				margin: 0 0 1rem 0;
320				font-size: 0.875rem;
321				color: var(--text-secondary);
322			}
323			.field .form-hint {
324				margin: 0.25rem 0 0 0;
325			}
326			input:user-invalid,
327			textarea:user-invalid,
328			[aria-invalid="true"] {
329				border-color: var(--error);
330				box-shadow: inset 0 0 0 1px var(--error);
331			}
332			.error-message {
333				display: block;
334				color: var(--error);
335				font-size: 0.875rem;
336				font-weight: 500;
337				margin-top: 0.25rem;
338			}
339			.error-message:empty {
340				display: none;
341			}
342			.live-region {
343				display: flex;
344				align-items: center;
345				min-height: 3.5rem;
346				margin-top: 1rem;
347				padding: 1rem;
348				border: 1px dashed var(--border);
349				border-radius: 0.25rem;
350			}
351			input:focus,
352			textarea:focus {
353				outline: 2px solid var(--accent);
354				outline-offset: 2px;
355				border-color: var(--accent);
356			}
357			@media print {
358				:root {
359					color-scheme: light;
360					--text: #000;
361					--text-secondary: #333;
362					--background: #fff;
363					--surface: #fff;
364					--accent: #000;
365					--border: #999;
366					--border-control: #000;
367					--error: #000;
368				}
369				.skip-link,
370				nav,
371				button,
372				.button,
373				.live-region {
374					display: none;
375				}
376				body {
377					display: block;
378					min-height: 0;
379					max-width: none;
380					padding: 0;
381				}
382				a {
383					color: inherit;
384					text-decoration: underline;
385				}
386				a[href^="http"]::after {
387					content: " (" attr(href) ")";
388					font-size: 0.85em;
389					font-weight: normal;
390				}
391				.card {
392					border: none;
393					break-inside: avoid;
394				}
395			}
396		</style>
397	</head>
398	<body>
399		<a class="skip-link" href="#main">Skip to content</a>
400		<header id="top">
401			<h1>Welcome</h1>
402			<nav aria-label="Page sections">
403				<ul>
404					<li><a href="#features">Features</a></li>
405					<li><a href="#examples">Examples</a></li>
406					<li><a href="#resources">Resources</a></li>
407				</ul>
408			</nav>
409		</header>
410		<main id="main" tabindex="-1">
411			<section aria-label="Introduction">
412				<p>This is a well-structured, accessible HTML5 document demonstrating modern best practices for semantic markup and inclusive design.</p>
413				<p>
414					It uses semantic landmarks, a skip link for keyboard navigation,
415					and CSS that adapts to your light or dark mode preference.
416				</p>
417				<p>
418					Text and link colors meet WCAG AA contrast in both themes, type scales
419					with your browser's font size, and motion respects your system settings.
420				</p>
421			</section>
422	
423			<section aria-labelledby="features">
424				<h2 id="features">Features</h2>
425				<ul>
426					<li>Semantic HTML structure with proper landmarks</li>
427					<li>Keyboard accessible navigation and focus management</li>
428					<li>Dark mode support with custom color schemes</li>
429					<li>Responsive typography using modern CSS</li>
430					<li>Print-friendly styles for better readability</li>
431					<li>WCAG AA contrast compliance in all color modes</li>
432				</ul>
433			</section>
434	
435			<section aria-labelledby="examples">
436				<h2 id="examples">Examples</h2>
437				<article class="card">
438					<h3>Component Cards</h3>
439					<p>Card components are useful for organizing related content. They include a subtle border and padding for visual separation.</p>
440					<a class="button" href="#resources">Learn more<span class="visually-hidden"> about accessibility resources</span></a>
441				</article>
442	
443				<article class="card">
444					<h3>Interactive Elements</h3>
445					<p>Buttons and links are fully accessible with clear focus states. All interactive elements include visible focus indicators and proper ARIA labels.</p>
446					<p><strong>Keyboard navigation:</strong> Use <kbd>Tab</kbd> to move forward, <kbd><kbd>Shift</kbd>+<kbd>Tab</kbd></kbd> to move backward, and <kbd>Enter</kbd> to activate.</p>
447				</article>
448	
449				<article class="card">
450					<h3>Accessible Form</h3>
451					<form id="contact-form" novalidate>
452						<p class="form-hint">Fields marked * are required.</p>
453						<div class="field">
454							<label for="email">Email <span aria-hidden="true">*</span></label>
455							<input type="email" id="email" name="email" autocomplete="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
456							<span id="email-error" class="error-message"></span>
457							<small id="email-help" class="form-hint">For example, name@example.com</small>
458						</div>
459						<div class="field">
460							<label for="message">Message</label>
461							<textarea id="message" name="message" rows="4" maxlength="2000" aria-describedby="message-help"></textarea>
462							<small id="message-help" class="form-hint">Up to 2,000 characters.</small>
463						</div>
464						<button type="submit">Send message</button>
465						<p id="form-status" role="status"></p>
466					</form>
467				</article>
468	
469				<article class="card">
470					<h3>Live Region Example</h3>
471					<p>Click the button to announce a message using a live region. This demonstrates how screen readers are notified of dynamic updates.</p>
472					<button id="announce" type="button">Announce message</button>
473					<div class="live-region" aria-live="polite" aria-atomic="true">
474						<span id="live-message"></span>
475					</div>
476				</article>
477			</section>
478	
479			<section aria-labelledby="resources">
480				<h2 id="resources">Resources</h2>
481				<p>Want to learn more about web accessibility and semantic HTML? Check out these resources:</p>
482				<ul>
483					<li><a href="https://www.w3.org/WAI/WCAG22/quickref/" target="_blank" rel="noopener noreferrer">WCAG 2.2 Quick Reference<span class="visually-hidden"> (opens in new tab)</span></a></li>
484					<li><a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener noreferrer">HTML Living Standard<span class="visually-hidden"> (opens in new tab)</span></a></li>
485					<li><a href="https://www.a11y-101.com/" target="_blank" rel="noopener noreferrer">A11y 101<span class="visually-hidden"> (opens in new tab)</span></a></li>
486				</ul>
487			</section>
488		</main>
489		<footer>
490			<nav aria-label="Footer links">
491				<ul>
492					<li><a href="#top">Back to top</a></li>
493					<li><a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub<span class="visually-hidden"> (opens in new tab)</span></a></li>
494				</ul>
495			</nav>
496			<p><small>&copy; <time datetime="2026">2026</time>. All rights reserved.</small></p>
497		</footer>
498		<script>
499			const messages = [
500				"This update was announced to screen readers!",
501				"Dynamic content updates work with aria-live regions.",
502				"Live regions are essential for accessible web apps.",
503				"Try this with a screen reader like NVDA or JAWS!"
504			];
505			let nextMessage = 0;
506			const announceBtn = document.getElementById('announce');
507			const contactForm = document.getElementById('contact-form');
508			const emailInput = document.getElementById('email');
509			const formStatus = document.getElementById('form-status');
510	
511			if (announceBtn) {
512				announceBtn.addEventListener('click', () => {
513					document.getElementById('live-message').textContent = messages[nextMessage];
514					nextMessage = (nextMessage + 1) % messages.length;
515				});
516			}
517	
518			if (contactForm) {
519				const emailError = document.getElementById('email-error');
520	
521				const validateEmail = () => {
522					let message = '';
523					if (emailInput.validity.valueMissing) {
524						message = 'Enter your email address.';
525					} else if (!emailInput.validity.valid) {
526						message = 'Enter an email address in the format name@example.com.';
527					}
528					emailError.textContent = message;
529					if (message) {
530						emailInput.setAttribute('aria-invalid', 'true');
531						emailInput.setAttribute('aria-describedby', 'email-error email-help');
532					} else {
533						emailInput.removeAttribute('aria-invalid');
534						emailInput.setAttribute('aria-describedby', 'email-help');
535					}
536					return !message;
537				};
538	
539				emailInput.addEventListener('blur', () => {
540					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
541						validateEmail();
542					}
543				});
544	
545				emailInput.addEventListener('input', () => {
546					if (emailInput.hasAttribute('aria-invalid')) {
547						validateEmail();
548					}
549				});
550	
551				contactForm.addEventListener('submit', (event) => {
552					event.preventDefault();
553					formStatus.textContent = '';
554					if (!validateEmail()) {
555						emailInput.focus();
556						return;
557					}
558					contactForm.reset();
559					setTimeout(() => {
560						formStatus.textContent = "Thanks! This is a demo, so nothing was sent.";
561					}, 100);
562				});
563			}
564		</script>
565	</body>
566	</html>
